    87	
    88	        private transient ValueState<Long> currentStageCount;
    89	        private transient ValueState<Long> currentStageLastSubmitTs;
    90	        private transient ValueState<Long> currentStageInactivityTimerTs;
    91	
    92	        private transient ValueState<Long> maxStageCount;
    93	
    94	        private transient ValueState<Long> jobFinishTimerTs;
    95	
    96	        private LongestStageOnTerminalEvent(long gapMillis) {
    97	            this.gapMillis = gapMillis;
    98	        }
    99	
   100	        @Override
   101	        public void open(Configuration parameters) {
   102	            currentStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("curCount", Long.class));
   103	            currentStageLastSubmitTs = getRuntimeContext().getState(new ValueStateDescriptor<>("curLastTs", Long.class));
   104	            currentStageInactivityTimerTs = getRuntimeContext().getState(new ValueStateDescriptor<>("curTimerTs", Long.class));
   105	            maxStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxCount", Long.class));
   106	            jobFinishTimerTs = getRuntimeContext().getState(new ValueStateDescriptor<>("finishTimerTs", Long.class));
   107	        }
   108	
   109	        @Override
   110	        public void processElement1(TaskEvent event, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
   111	            long ts = event.getTimestampMillis();
   112	
   113	            Long lastTs = currentStageLastSubmitTs.value();
   114	            Long curCount = currentStageCount.value();
   115	            if (curCount == null) {
   116	                curCount = 0L;
   117	            }
   118	
   119	            // If this SUBMIT is after a 10-minute inactivity gap, close the previous stage.
   120	            if (lastTs != null && ts - lastTs > gapMillis) {
   121	                closeStageIfOpen();
   122	                lastTs = null;
   123	                curCount = 0L;
   124	            }
   125	
   126	            curCount += 1;
   127	            currentStageCount.update(curCount);
   128	            currentStageLastSubmitTs.update(ts);
   129	
   130	            // Re-arm inactivity timer for the current stage.
   131	            Long oldTimer = currentStageInactivityTimerTs.value();
   132	            if (oldTimer != null) {
   133	                ctx.timerService().deleteEventTimeTimer(oldTimer);
   134	            }
   135	            long newTimer = ts + gapMillis;
   136	            currentStageInactivityTimerTs.update(newTimer);
   137	            ctx.timerService().registerEventTimeTimer(newTimer);
   138	        }
   139	
   140	        @Override
   141	        public void processElement2(JobEvent event, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
   142	            long finishTimer = event.getTimestampMillis() + gapMillis;
   143	
   144	            Long oldFinishTimer = jobFinishTimerTs.value();
   145	            if (oldFinishTimer != null) {
   146	                ctx.timerService().deleteEventTimeTimer(oldFinishTimer);
   147	            }
   148	            jobFinishTimerTs.update(finishTimer);
   149	            ctx.timerService().registerEventTimeTimer(finishTimer);
   150	        }
   151	
   152	        @Override
   153	        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
   154	            Long stageTimer = currentStageInactivityTimerTs.value();
   155	            if (stageTimer != null && stageTimer == timestamp) {
   156	                closeStageIfOpen();
   157	            }
   158	
   159	            Long finishTimer = jobFinishTimerTs.value();
   160	            if (finishTimer != null && finishTimer == timestamp) {
   161	                // Ensure any still-open stage is closed.
   162	                closeStageIfOpen();
   163	
   164	                Long max = maxStageCount.value();
   165	                if (max == null) {
   166	                    max = 0L;
   167	                }
   168	
   169	                out.collect(Tuple2.of(ctx.getCurrentKey(), max));
   170	                clearAll();
   171	            }
   172	        }
   173	
   174	        private void closeStageIfOpen() throws Exception {
   175	            Long curCount = currentStageCount.value();
   176	            if (curCount == null || curCount == 0L) {
   177	                currentStageCount.clear();
   178	                currentStageLastSubmitTs.clear();
   179	                currentStageInactivityTimerTs.clear();
   180	                return;
   181	            }
   182	
   183	            Long max = maxStageCount.value();
   184	            if (max == null || curCount > max) {
   185	                maxStageCount.update(curCount);
   186	            }
   187	
   188	            currentStageCount.clear();
   189	            currentStageLastSubmitTs.clear();
   190	            currentStageInactivityTimerTs.clear();
   191	        }
   192	
   193	        private void clearAll() throws Exception {
   194	            currentStageCount.clear();
   195	            currentStageLastSubmitTs.clear();
   196	            currentStageInactivityTimerTs.clear();
   197	            maxStageCount.clear();
   198	            jobFinishTimerTs.clear();
   199	        }
