    private static final class TaskEventFileSource implements SourceFunction<TaskEvent> {
        private final String path;
        private volatile boolean running = true;

        private TaskEventFileSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            try (BufferedReader br = new BufferedReader(new InputStreamReader(openPossiblyGzipped(path), StandardCharsets.UTF_8))) {
                String line;
                while (running && (line = br.readLine()) != null) {
                    if (line.isEmpty()) {
                        continue;
                    }
                    TaskEvent event = TaskEvent.fromString(line);
                    synchronized (ctx.getCheckpointLock()) {
                        ctx.collect(event);
