import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.FilterFunction;
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.datastream.KeyedStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.sink.SinkFunction;
import org.apache.flink.util.Collector;

import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);

        // Session size in seconds (default: 10 minutes)
        final int sesssize = params.getInt("sesssize", 600);
        final long gapMillis = sesssize * 1000L;

        if (taskInput == null || jobInput == null || outputPath == null) {
            throw new IllegalArgumentException("Required parameters: --task_input --job_input --output");
        }

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        DataStream<TaskEvent> submitTasks = env
                .readTextFile(taskInput)
                .map((MapFunction<String, TaskEvent>) TaskEvent::fromString)
                .filter((FilterFunction<TaskEvent>) e -> e.eventType == TaskEvent.EVENT_SUBMIT)
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((e, ts) -> e.getTimestampMillis())
                );

        DataStream<JobEvent> terminalJobs = env
                .readTextFile(jobInput)
                .map((MapFunction<String, JobEvent>) JobEvent::fromString)
                .filter((FilterFunction<JobEvent>) JobEvent::isTerminal)
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((e, ts) -> e.getTimestampMillis())
                );

        KeyedStream<TaskEvent, Long> submitByJob = submitTasks.keyBy(TaskEvent::getJobId);
        KeyedStream<JobEvent, Long> terminalByJob = terminalJobs.keyBy(JobEvent::getJobId);

        DataStream<Tuple2<Long, Long>> longestStagePerFinishedJob = submitByJob
                .connect(terminalByJob)
                .process(new LongestStageOnTerminalEvent(gapMillis));

        DataStream<String> formatted = longestStagePerFinishedJob
                .map((MapFunction<Tuple2<Long, Long>, String>) t -> "(" + t.f0 + "," + t.f1 + ")");

        SinkFunction<String> sink = sinkOrTest(new LocalFileSink(outputPath));
        formatted.addSink((SinkFunction<String>) sink).setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    private static final class LongestStageOnTerminalEvent
            extends KeyedCoProcessFunction<Long, TaskEvent, JobEvent, Tuple2<Long, Long>> {

        private final long gapMillis;

        private transient ValueState<Long> currentStageCount;
        private transient ValueState<Long> currentStageLastSubmitTs;
        private transient ValueState<Long> currentStageInactivityTimerTs;

        private transient ValueState<Long> maxStageCount;

        private transient ValueState<Long> jobFinishTimerTs;

        private LongestStageOnTerminalEvent(long gapMillis) {
            this.gapMillis = gapMillis;
        }

        @Override
        public void open(Configuration parameters) {
            currentStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("curCount", Long.class));
            currentStageLastSubmitTs = getRuntimeContext().getState(new ValueStateDescriptor<>("curLastTs", Long.class));
            currentStageInactivityTimerTs = getRuntimeContext().getState(new ValueStateDescriptor<>("curTimerTs", Long.class));
            maxStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxCount", Long.class));
            jobFinishTimerTs = getRuntimeContext().getState(new ValueStateDescriptor<>("finishTimerTs", Long.class));
        }

        @Override
        public void processElement1(TaskEvent event, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            long ts = event.getTimestampMillis();

            Long lastTs = currentStageLastSubmitTs.value();
            Long curCount = currentStageCount.value();
            if (curCount == null) {
                curCount = 0L;
            }

            // If this SUBMIT is after a 10-minute inactivity gap, close the previous stage.
            if (lastTs != null && ts - lastTs > gapMillis) {
                closeStageIfOpen();
                lastTs = null;
                curCount = 0L;
            }

            curCount += 1;
            currentStageCount.update(curCount);
            currentStageLastSubmitTs.update(ts);

            // Re-arm inactivity timer for the current stage.
            Long oldTimer = currentStageInactivityTimerTs.value();
            if (oldTimer != null) {
                ctx.timerService().deleteEventTimeTimer(oldTimer);
            }
            long newTimer = ts + gapMillis;
            currentStageInactivityTimerTs.update(newTimer);
            ctx.timerService().registerEventTimeTimer(newTimer);
        }

        @Override
        public void processElement2(JobEvent event, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            long finishTimer = event.getTimestampMillis() + gapMillis;

            Long oldFinishTimer = jobFinishTimerTs.value();
            if (oldFinishTimer != null) {
                ctx.timerService().deleteEventTimeTimer(oldFinishTimer);
            }
            jobFinishTimerTs.update(finishTimer);
            ctx.timerService().registerEventTimeTimer(finishTimer);
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            Long stageTimer = currentStageInactivityTimerTs.value();
            if (stageTimer != null && stageTimer == timestamp) {
                closeStageIfOpen();
            }

            Long finishTimer = jobFinishTimerTs.value();
            if (finishTimer != null && finishTimer == timestamp) {
                // Ensure any still-open stage is closed.
                closeStageIfOpen();

                Long max = maxStageCount.value();
                if (max == null) {
                    max = 0L;
                }

                out.collect(Tuple2.of(ctx.getCurrentKey(), max));
                clearAll();
            }
        }

        private void closeStageIfOpen() throws Exception {
            Long curCount = currentStageCount.value();
            if (curCount == null || curCount == 0L) {
                currentStageCount.clear();
                currentStageLastSubmitTs.clear();
                currentStageInactivityTimerTs.clear();
                return;
            }

            Long max = maxStageCount.value();
            if (max == null || curCount > max) {
                maxStageCount.update(curCount);
            }

            currentStageCount.clear();
            currentStageLastSubmitTs.clear();
            currentStageInactivityTimerTs.clear();
        }

        private void clearAll() throws Exception {
            currentStageCount.clear();
            currentStageLastSubmitTs.clear();
            currentStageInactivityTimerTs.clear();
            maxStageCount.clear();
            jobFinishTimerTs.clear();
        }
    }

    private static final class LocalFileSink implements SinkFunction<String> {
        private final String outputPath;

        private transient BufferedWriter writer;

        private LocalFileSink(String outputPath) {
            this.outputPath = outputPath;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            Path p = Path.of(outputPath);
            Path parent = p.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }

            writer = Files.newBufferedWriter(
                    p,
                    StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE,
                    StandardOpenOption.TRUNCATE_EXISTING
            );
        }

        @Override
        public synchronized void invoke(String value, Context context) throws Exception {
            writer.write(value);
            writer.newLine();
        }

        @Override
        public void close() throws IOException {
            if (writer != null) {
                writer.flush();
                writer.close();
            }
        }
    }
}
